<script setup>
import {computed,ref,watch} from 'vue';
import {useRouter,useRoute} from 'vue-router';
import {ElMessage} from 'element-plus';
import * as icons from '@element-plus/icons-vue';
import {session,api,can} from './api.js';
import {resources,viewPermissionsFor} from './resources.js';
const router=useRouter(),route=useRoute(),mobileOpen=ref(false),passwordOpen=ref(false),oldPassword=ref(''),newPassword=ref(''),saving=ref(false);
const menus=computed(()=>Object.entries(resources).filter(([key])=>(!resources[key].superuserOnly||session.user.is_superuser)&&viewPermissionsFor(key).some(can)));
const content=computed(()=>menus.value.filter(([key])=>!['users','roles','audit-logs'].includes(key)));
const system=computed(()=>menus.value.filter(([key])=>['users','roles','audit-logs'].includes(key)));
watch(()=>route.path,()=>mobileOpen.value=false);
const storefront=import.meta.env.DEV?'http://127.0.0.1:4173/':'/';
async function logout(){try{await api('auth/session/',{method:'DELETE'});session.user=null;await router.push('/login');}catch(e){ElMessage.error(e.message);}}
async function changePassword(){saving.value=true;try{await api('auth/password/',{method:'POST',body:{old_password:oldPassword.value,new_password:newPassword.value}});passwordOpen.value=false;oldPassword.value='';newPassword.value='';ElMessage.success('密码已更新');}catch(e){ElMessage.error(e.message);}finally{saving.value=false;}}
</script>
<template><router-view v-if="route.path==='/login'"/><div v-else-if="session.user" class="admin-shell"><button v-if="mobileOpen" class="sidebar-shade" aria-label="收起菜单" @click="mobileOpen=false"></button><aside class="sidebar" :class="{open:mobileOpen}"><router-link to="/" class="wordmark">POPOMO<span>™</span></router-link><div class="workspace-label"><span class="status-dot"></span> 管理工作台 <span class="workspace-version">01</span></div><nav aria-label="后台功能"><router-link to="/" class="nav-link" :class="{selected:route.path==='/'}"><el-icon><icons.DataBoard/></el-icon>概览</router-link><template v-for="[label,items] in [['内容与业务',content],['系统管理',system]]" :key="label"><p v-if="items.length" class="nav-group">{{label}}</p><router-link v-for="[key,item] in items" :key="key" :to="'/'+key" class="nav-link" :class="{selected:route.path==='/'+key}"><el-icon><component :is="icons[item.icon]"/></el-icon>{{item.title}}</router-link></template></nav><a class="visit-store" :href="storefront" target="_blank" rel="noopener">打开用户端 <el-icon><icons.TopRight/></el-icon></a><div class="sidebar-foot">GOOD DESIGN. GOOD DAYS.</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="打开菜单" @click="mobileOpen=true"><el-icon><icons.Menu/></el-icon></button><span>工作空间</span><span class="slash">/</span><strong>{{resources[route.meta.resource]?.title||'概览'}}</strong></div><div class="account"><span class="avatar">{{session.user.name.slice(0,1).toUpperCase()}}</span><span>{{session.user.name}}</span><el-dropdown trigger="click"><el-button text aria-label="账号选项"><el-icon><icons.ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="passwordOpen=true">修改密码</el-dropdown-item><el-dropdown-item @click="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><main class="main-content"><router-view :key="route.path"/></main><footer class="page-footer">POPOMO ADMIN <span>让创意有序发生。</span></footer></div><el-dialog v-model="passwordOpen" title="修改登录密码" width="420px"><el-form label-position="top" @submit.prevent="changePassword"><el-form-item label="当前密码"><el-input v-model="oldPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码（至少 12 位）"><el-input v-model="newPassword" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="passwordOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="changePassword">更新密码</el-button></template></el-dialog></div><div v-else class="loading-screen">正在连接管理工作台…</div></template>
